script:
(function () {
  'use strict';
  // Specialty vehicle (ATV, snowmobile, golf cart, trailer, personal watercraft) on a short loan:
  // seasonal payment plans, cost per use and own-vs-rent break-even.
  //   Loan = price + attachments - down - trade-in + owed (+ sales tax and fees when financed), >= 0.
  //   Simple interest accrues monthly at APR / 12 on the principal balance; each payment covers accrued
  //   interest first, then principal (unpaid interest is carried, not compounded).
  //   Every-month plan: payment is due in months 1..n. Seasonal plan: over the same n months, payment is
  //   due only in month m when (n - m) mod 12 < P, i.e. P paid months in each 12-month cycle counted back
  //   from the final payment, with the 12 - P skipped months at the start of each cycle. The level payment that clears the loan by
  //   month n is found by bisection (with P = 12 it equals M = L x i / (1 - (1 + i)^-n)).
  //   Value after y years = (price + attachments) x (1 - d)^y.
  //   Cost of owning over H years = drop in value + interest paid in H years + sales tax + fees
  //     + (insurance and registration + maintenance and storage) x H. Cost per use = that / (uses x H).
  //   Break-even uses a year = yearly cost of owning / rental price per day.
  // Presets per vehicle type are rough illustrative starting points, not market data.
  // Verified in Node (scratchpad tests/autogroup/sv.test.js): $12,000 at 8% for 48 months = $292.96/mo
  //   (closed form) and the every-month simulation matches it; a seasonal plan (8 of 12 months) clears the
  //   balance to within a cent by month n; its payment ($444.91 on $12,000 at 8%, 48 months) is within 0.2% of,
  //   and just below, the compound-interest closed form L / sum(v^k over paid months) = $445.38, as expected
  //   because skipped interest is not compounded; it costs more interest than paying every month; at 0% the
  //   seasonal payment equals L / number of paid months; blank, zero and negative inputs show an error and
  //   no NaN or Infinity reaches the page.
  var PRESETS = {
    atv: { price: 12000, term: 48, dep: 12, ins: 300, upkeep: 500, uses: 30, rent: 225 },
    snowmobile: { price: 14000, term: 48, dep: 12, ins: 250, upkeep: 500, uses: 20, rent: 275 },
    golfcart: { price: 11000, term: 48, dep: 10, ins: 200, upkeep: 300, uses: 80, rent: 80 },
    trailer: { price: 6000, term: 36, dep: 6, ins: 100, upkeep: 150, uses: 15, rent: 75 },
    pwc: { price: 13000, term: 48, dep: 10, ins: 350, upkeep: 600, uses: 20, rent: 300 }
  };
  var FIELDS = { price: 'svPrice', term: 'svTerm', dep: 'svDep', ins: 'svIns', upkeep: 'svUpkeep', uses: 'svUses', rent: 'svRent' };
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  // Counted back from the final month, so the loan always ends on a payment month and runs the full term.
  function isPaid(m, paidMonths, term) { return m <= term && (term - m) % 12 < paidMonths; }

  // Runs the loan for `months` months (may exceed the term) at a level payment. Returns the residual
  // at the term, totals and per-month records.
  function run(loan, apr, term, paidMonths, pmt, horizon) {
    var i = apr / 1200, bal = loan, accrued = 0, recs = [], residual = 0;
    var end = Math.max(term, horizon || 0);
    for (var m = 1; m <= end; m++) {
      var interest = bal * i, pay = 0;
      if (bal > 0.005 || accrued > 0.005) {
        accrued += interest;
        if (isPaid(m, paidMonths, term)) {
          pay = Math.min(pmt, bal + accrued);
          var toInt = Math.min(pay, accrued);
          accrued -= toInt;
          bal -= pay - toInt;
        }
      } else { interest = 0; }
      if (m === term) residual = bal + accrued;
      recs.push({ pay: pay, interest: interest, bal: bal + accrued });
    }
    return { residual: residual, recs: recs };
  }

  function levelPayment(loan, apr, term, paidMonths) {
    if (loan <= 0) return 0;
    var count = 0;
    for (var m = 1; m <= term; m++) if (isPaid(m, paidMonths, term)) count++;
    if (apr === 0) return loan / count;
    var lo = 0, hi = loan * (1 + apr / 1200 * term) + 1;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (run(loan, apr, term, paidMonths, mid).residual > 0) lo = mid; else hi = mid;
    }
    return hi;
  }

  function schedule(o, loan, paidMonths) {
    var pmt = levelPayment(loan, o.apr, o.months, paidMonths);
    var r = run(loan, o.apr, o.months, paidMonths, pmt, o.years * 12);
    var totalPaid = 0;
    r.recs.forEach(function (x) { totalPaid += x.pay; });
    return { pmt: pmt, recs: r.recs, interest: Math.max(0, totalPaid - loan) };
  }

  function applyPreset() {
    var p = PRESETS[el('svType').value];
    if (!p) return;
    Object.keys(FIELDS).forEach(function (k) { el(FIELDS[k]).value = String(p[k]); });
  }

  function togglePlan() {
    var seasonal = el('svPlan').value === 'seasonal';
    el('svPaidWrap').className = seasonal ? '' : 'form-field-hidden';
  }

  var OUT = ['svPayment', 'svPerUse', 'svBreakEven', 'svTotalInterest', 'svLoanOut', 'svMonthlyPay', 'svMonthlyInt', 'svExtraInt',
             'svOwnYear', 'svRentYear', 'svValue', 'svBalance', 'svTotal', 'svRentVerdict'];

  function clearResults() {
    OUT.forEach(function (id) { setText(id, '–'); });
    el('svSchedule').innerHTML = '';
  }

  function update() {
    togglePlan();
    var o = {
      price: read('svPrice'), extras: read('svExtras', true), down: read('svDown', true), apr: read('svApr'), months: read('svTerm'),
      taxRate: read('svTaxRate', true), fees: read('svFees', true), years: read('svYears'), uses: read('svUses', true),
      ins: read('svIns', true), upkeep: read('svUpkeep', true), dep: read('svDep', true), rent: read('svRent', true),
      trade: read('svTrade', true), owed: read('svOwed', true), paid: el('svPlan').value === 'seasonal' ? read('svPaid') : 12,
      finance: el('svFinanceCosts').checked, tradeCredit: el('svTradeCredit').checked
    };
    var error = el('svError'), msg = '';
    if (isNaN(o.price) || o.price <= 0) msg = 'Enter a purchase price greater than $0.';
    else if (isNaN(o.apr) || o.apr < 0 || o.apr > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if (isNaN(o.months) || o.months < 6 || o.months > 120 || o.months % 1 !== 0) msg = 'Enter a loan term of 6 to 120 whole months.';
    else if (isNaN(o.paid) || o.paid < 1 || o.paid > 12 || o.paid % 1 !== 0) msg = 'Enter 1 to 12 months of payments a year.';
    else if (isNaN(o.years) || o.years < 1 || o.years > 20 || o.years % 1 !== 0) msg = 'Enter 1 to 20 whole years of ownership.';
    else if ([o.extras, o.down, o.taxRate, o.fees, o.uses, o.ins, o.upkeep, o.dep, o.rent, o.trade, o.owed].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (o.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (o.dep >= 100) msg = 'Enter a yearly drop in value below 100%.';
    else if (o.uses > 366) msg = 'Enter at most 366 days of use a year.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var cost = o.price + o.extras;
    var taxable = Math.max(0, cost - (o.tradeCredit ? o.trade : 0));
    var tax = taxable * o.taxRate / 100;
    var loan = Math.max(0, cost - o.down - o.trade + o.owed + (o.finance ? tax + o.fees : 0));
    var plan = schedule(o, loan, o.paid);
    var every = o.paid === 12 ? plan : schedule(o, loan, 12);

    var H = o.years * 12, interestH = 0, rows = [], value = cost;
    for (var m = 1; m <= H; m++) {
      var rec = plan.recs[m - 1], y = Math.ceil(m / 12);
      interestH += rec.interest;
      if (!rows[y - 1]) rows[y - 1] = { year: y, paid: 0, interest: 0 };
      rows[y - 1].paid += rec.pay; rows[y - 1].interest += rec.interest;
      if (m % 12 === 0) {
        var nv = cost * Math.pow(1 - o.dep / 100, y);
        rows[y - 1].dep = value - nv; value = nv; rows[y - 1].value = nv; rows[y - 1].bal = rec.bal;
      }
    }
    var running = o.ins + o.upkeep;
    var total = (cost - value) + interestH + tax + o.fees + running * o.years;
    var perYear = total / o.years;
    var balH = rows[o.years - 1].bal;

    setText('svPayment', loan > 0.005 ? money.format(plan.pmt) + (o.paid < 12 ? ' × ' + o.paid + ' months a year' : ' a month') : '$0.00');
    setText('svTotalInterest', money.format(plan.interest));
    setText('svPerUse', o.uses > 0 ? money.format(total / (o.uses * o.years)) : 'No uses entered');
    setText('svBreakEven', o.rent > 0 ? Math.ceil(perYear / o.rent - 1e-9) + ' days a year' : 'No rental price');
    setText('svLoanOut', money.format(loan));
    setText('svMonthlyPay', money.format(every.pmt));
    setText('svMonthlyInt', money.format(every.interest));
    setText('svExtraInt', o.paid < 12 ? money.format(Math.max(0, plan.interest - every.interest)) : 'Not using a seasonal plan');
    setText('svOwnYear', money.format(perYear));
    setText('svRentYear', money.format(o.rent * o.uses));
    setText('svValue', money.format(value));
    setText('svBalance', money.format(balH));
    setText('svTotal', money.format(total));
    if (o.rent > 0 && o.uses > 0) {
      var diff = perYear - o.rent * o.uses;
      setText('svRentVerdict', diff > 0
        ? 'At ' + o.uses + ' days a year, renting would cost about ' + money.format(diff) + ' a year less than owning.'
        : 'At ' + o.uses + ' days a year, owning costs about ' + money.format(-diff) + ' a year less than renting.');
    } else {
      setText('svRentVerdict', 'Enter days of use and a rental price to compare owning with renting.');
    }

    el('svSchedule').innerHTML = rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money0.format(row.paid) + '</td><td>' + money0.format(row.interest) + '</td><td>' +
        money0.format(running) + '</td><td>' + money0.format(row.dep) + '</td><td>' + money0.format(row.bal) + '</td><td>' + money0.format(row.value) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('svForm');
    if (!form) return;
    el('svType').addEventListener('change', applyPreset);
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
